E = sys.argv[1]; B = sys.argv[2]; OUT = sys.argv[3]
def ch(title, typ, labels, series, fmt="pct0", **kw):
    d = {"kind": "chart", "title": title, "type": typ, "labels": labels, "series": series, "fmt": fmt}
    d.update(kw); return d
def ser(name, values, color="navy"): return {"name": name, "values": values, "color": color}
def q(tracker, title, answer, foot, blocks, insights):
    return {"type": "q", "tracker": tracker, "title": title, "answer": answer, "foot": foot, "blocks": blocks, "insights": insights}
