b64 = lambda p: base64.b64encode(open(p, "rb").read()).decode()
data = json.dumps({"slides": slides}, ensure_ascii=False).replace("<", "\\u003c")
out = tpl.replace("__LOGO_WHITE__", b64(B + "/logo_white.png")).replace("__LOGO__", b64(B + "/logo.png")).replace("__DATA__", data)
open(OUT, "w").write(out); print(len(out), "bytes")
